+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code nameText}
+ * appears in its first or last name (ignoring case and accents), and, if any
+ * statuses are given, its status is one of them.
+ *
+ * @param nameText free text as entered by the user; may be empty
+ * @param statuses statuses to include; empty means every status
+ */
+public record CustomerFilter(String nameText, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        nameText = nameText == null ? "" : nameText.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return nameText.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The normalized search terms. */
+    public List<String> terms() {
+        String normalized = normalize(nameText);
+        return normalized.isBlank()
+                ? List.of()
+                : Arrays.asList(normalized.strip().split("\\s+"));
+    }
+
+    /** Lower-cases text and strips accents, so {@code Mäkinen} becomes {@code makinen}. */
+    public static String normalize(String text) {
+        if (text == null) {
+            return "";
+        }
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
